#!/usr/bin/env sh
# Bundle Desktop's bot face engine for the site, so the landing shows the
# real faces (no copy to drift). Rerun after changing
# apps/desktop/renderer/src/lib/features/bots/face/.
set -e
root="$(cd "$(dirname "$0")/../.." && pwd)"
"$root/apps/desktop/renderer/node_modules/.bin/esbuild" \
  "$root/apps/desktop/renderer/src/lib/features/bots/face/engine.ts" \
  --bundle --format=esm --minify --target=es2020 \
  --banner:js="// Generated by site/scripts/build-faces.sh from Desktop's face engine. Do not edit." \
  --outfile="$root/site/js/faces.js"
